CREATE TABLE public.library_entry_likes ( id uuid DEFAULT gen_random_uuid() PRIMARY KEY, entry_id uuid NOT NULL REFERENCES public.library_entries(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL, UNIQUE(entry_id, user_id) ); ALTER TABLE public.library_entry_likes ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users can see all likes" ON public.library_entry_likes FOR SELECT USING (true); CREATE POLICY "Users can insert their own likes" ON public.library_entry_likes FOR INSERT WITH CHECK (auth.uid() = user_id); CREATE POLICY "Users can delete their own likes" ON public.library_entry_likes FOR DELETE USING (auth.uid() = user_id);
